CREATE TABLE en1993_document(id INTEGER PRIMARY KEY CHECK(id=1),annex TEXT NOT NULL CHECK(annex IN ('En','De')),reliability_class TEXT NOT NULL CHECK(reliability_class IN ('RC1','RC2','RC3')));
